public sealed class CheckoutFacade
{
    private readonly IPricingService _pricing;
    private readonly IPaymentGateway _payments;
    private readonly IOrderStore _orders;
    public CheckoutFacade(IPricingService p, IPaymentGateway pay, IOrderStore o)
        => (_pricing, _payments, _orders) = (p, pay, o);
    public Task<OrderId> CheckoutAsync(Cart cart, CancellationToken ct = default)
        => _orders.SaveAsync(await _payments.ChargeAsync(_pricing.Price(cart), ct), ct);
}
